if(this.navSet){this.navSet.split(',').forEach(function(pair){var idx=pair.indexOf('=');if(idx===-1)return;var key=pair.slice(0,idx).trim();var val=pair.slice(idx+1).trim().replace('{iso}',iso).replace('{monday}',monday);params.set(key,val)})}
